// GLSL ES 3.00 for the globe. GLOBE team. DESIGN 6.1, 6.2, 6.5.
//
// Four programs and no more: the planet body, the atmosphere shell, the ribbon that draws
// every stroke in the scene, and the endpoint marker. There is no scene graph, no material
// system and no texture of any kind. DESIGN 6.2 is explicit that a photographic Earth reads as
// a template on sight, and the globe contract pins earthTexture to null.
//
// The ribbon vertex shader embeds the block generated by ./pipeline.js verbatim, and
// test/globe-pipeline.test.js asserts it is still there. That is the mechanism that stops the
// GPU path and the reference rasterizer from drifting apart.
//
// Isomorphic: no node:* imports and no DOM. These are strings.

import { RIBBON_EXPANSION_GLSL } from './pipeline.js';

const HEAD = '#version 300 es\n';
const FS_HEAD = '#version 300 es\nprecision highp float;\n';

/**
 * The planet body.
 *
 * There is no light source. A lit globe implies a sun position, a sun position implies a time
 * of day, and this product knows nothing about a time of day. What separates the disc from a
 * page of the same near black is a Fresnel lift towards the raised surface token at the limb,
 * which is a property of the viewing angle and claims nothing.
 */
export const SPHERE_VS = HEAD + `
in vec3 aPosition;
uniform mat4 uViewProj;
uniform vec3 uEye;
uniform float uRadius;
out vec3 vNormal;
out vec3 vWorld;

void main() {
  vec3 p = aPosition * uRadius;
  vNormal = normalize(aPosition);
  vWorld = p;
  gl_Position = uViewProj * vec4(p, 1.0);
}
`;

export const SPHERE_FS = FS_HEAD + `
in vec3 vNormal;
in vec3 vWorld;
uniform vec3 uEye;
uniform vec3 uOcean;
uniform vec3 uOceanRim;
uniform float uRimAlpha;
out vec4 outColor;

void main() {
  vec3 view = normalize(uEye - vWorld);
  float facing = clamp(dot(normalize(vNormal), view), 0.0, 1.0);
  float fresnel = pow(1.0 - facing, 3.0);
  outColor = vec4(mix(uOcean, uOceanRim, fresnel * uRimAlpha), 1.0);
}
`;

/**
 * The atmosphere. One backface rendered shell with a Fresnel term, half resolution
 * (globe contract atmosphereResolutionScale), additive, depth tested but not depth writing.
 *
 * Front faces are culled, so what is drawn is the FAR half of the shell, and the planet
 * occludes all of it except the ring that falls outside the silhouette. That ring is the glow.
 * It is one draw call and about thirty lines, and DESIGN 6.1 is right that it is most of why a
 * globe looks expensive.
 */
export const ATMOSPHERE_VS = SPHERE_VS;

export const ATMOSPHERE_FS = FS_HEAD + `
in vec3 vNormal;
in vec3 vWorld;
uniform vec3 uEye;
uniform vec3 uAtmosphere;
uniform float uAlpha;
uniform float uRadius;
out vec4 outColor;

void main() {
  // The glow is a function of how close the eye ray through this fragment passes to the centre
  // of the planet, NOT of the shell's own facing angle. That distinction is the difference
  // between a glow that hugs the limb and a flat grey donut: a Fresnel term on the shell peaks
  // at the OUTER edge of the shell, which is the wrong edge. The impact parameter peaks at the
  // planet's own silhouette, which is where an atmosphere actually is.
  vec3 ray = normalize(vWorld - uEye);
  float b = length(uEye - ray * dot(uEye, ray));
  // INSIDE THE PLANET'S OWN SILHOUETTE THERE IS NO GLOW AT ALL, and this guard is the whole
  // difference between a limb and a wash.
  //
  // Without it, every ray with an impact parameter under 1.0 clamps to t = 1 and gets the
  // maximum glow, so the shell adds its full colour across the entire disc rather than only
  // around it. Depth testing is supposed to prevent that by letting the planet occlude the far
  // side of the shell, and on the machine this was measured on it did not: the planet body
  // came back a flat 82, 89, 96 against the near black DESIGN 6.2 specifies for the ocean, with
  // no shading variation anywhere across it. Relying on the depth buffer to enforce something
  // the shader can state directly is relying on a second mechanism to fix the first one.
  float inside = step(1.0, b);
  float t = inside * clamp((uRadius - b) / (uRadius - 1.0), 0.0, 1.0);
  float rim = pow(t, 3.0);
  // Premultiplied, because the blend is ONE, ONE. Writing a straight alpha here and blending
  // additively multiplies the colour in twice and blows the rim out to white, which is the one
  // colour DESIGN 6.2 says the coastline may never be either.
  outColor = vec4(uAtmosphere * rim * uAlpha, rim * uAlpha);
}
`;

/**
 * The ribbon. Every stroke in the scene goes through this one program: coastlines, arcs and
 * nothing else, because there is nothing else.
 *
 * uProgress is the draw in from DESIGN 5: as each region's first response lands, its arc draws
 * from the observer outwards. uFlowPhase is the dash travelling along arc length from
 * DESIGN 6.2, which is a dash and not a particle system, deliberately. Under reduced motion
 * the caller passes uFlowAlpha of zero and uProgress of one and the whole thing is static.
 */
export const RIBBON_VS = HEAD + `
in vec3 aPosition;
in vec3 aTangent;
in float aSide;
in float aArcT;

uniform mat4 uViewProj;
uniform vec2 uViewportPx;
uniform float uHalfWidthPx;

out float vSide;
out float vArcT;

void main() {
  vSide = aSide;
  vArcT = aArcT;
${RIBBON_EXPANSION_GLSL}
}
`;

export const RIBBON_FS = FS_HEAD + `
in float vSide;
in float vArcT;

uniform vec3 uColor;
uniform float uAlpha;
uniform float uProgress;
uniform float uFeather;
uniform float uFlowAlpha;
uniform float uFlowPhase;
uniform float uDashCount;

out vec4 outColor;

void main() {
  // The draw in. Discarding rather than scaling the geometry keeps the arc length parameter
  // meaningful and keeps one vertex buffer valid for every frame of the animation.
  if (vArcT > uProgress) discard;

  // Across the ribbon, vSide runs -1 to 1. Feathering the last pixel is what stops a 1.4 pixel
  // stroke looking like a 1 pixel stair, and it is the reason this is worth doing at all.
  float across = 1.0 - abs(vSide);
  float cover = smoothstep(0.0, uFeather, across);

  float travelling = pow(max(0.0, sin((vArcT * uDashCount - uFlowPhase) * 6.28318530718)), 12.0);
  float a = uAlpha * cover;
  float glow = travelling * uFlowAlpha * cover;

  // Premultiplied again, so one blend mode (ONE, ONE_MINUS_SRC_ALPHA) serves both the stroke
  // and the additive dash on top of it without a second pass.
  outColor = vec4(uColor * (a + glow), a);
}
`;

/**
 * Endpoint markers. Screen aligned quads cut to a disc in the fragment shader.
 *
 * Not gl.POINTS. gl_PointSize above the implementation maximum is silently clamped, the
 * maximum is permitted to be small, and point sprites do not antialias. The same family of
 * reason that rules out gl.LINES rules this out too.
 */
export const MARKER_VS = HEAD + `
in vec3 aCentre;
in vec2 aCorner;

uniform mat4 uViewProj;
uniform vec2 uViewportPx;
uniform float uSizePx;

out vec2 vCorner;

void main() {
  vCorner = aCorner;
  vec4 clip = uViewProj * vec4(aCentre, 1.0);
  vec2 ndc = clip.xy / clip.w;
  vec2 offsetNdc = aCorner * uSizePx * 2.0 / uViewportPx;
  gl_Position = vec4((ndc + offsetNdc) * clip.w, clip.z, clip.w);
}
`;

export const MARKER_FS = FS_HEAD + `
in vec2 vCorner;
uniform vec3 uColor;
uniform float uAlpha;
uniform float uFeather;
out vec4 outColor;

void main() {
  float r = length(vCorner);
  if (r > 1.0) discard;
  float cover = 1.0 - smoothstep(1.0 - uFeather, 1.0, r);
  outColor = vec4(uColor * (uAlpha * cover), uAlpha * cover);
}
`;

/** Named so the renderer, the tests and a reader all use the same labels. */
export const PROGRAMS = Object.freeze({
  sphere: Object.freeze({ vs: SPHERE_VS, fs: SPHERE_FS }),
  atmosphere: Object.freeze({ vs: ATMOSPHERE_VS, fs: ATMOSPHERE_FS }),
  ribbon: Object.freeze({ vs: RIBBON_VS, fs: RIBBON_FS }),
  marker: Object.freeze({ vs: MARKER_VS, fs: MARKER_FS }),
});
